INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 1, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 3.414, "2025/01/31 12:00:00", 62, 1000001, 1, 190805, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 3.099, "2025/01/31 12:00:00", 62, 1000002, 1, 190805, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 3, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 2.801, "2025/01/31 12:00:00", 63, 1000003, 1, 190805, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 4, 2, "報酬がもらえますよ！\nチェックしてみてください", 2, 0.0, "2025/01/31 12:00:00", 63, 1000004, 1, 190805, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 5, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 2.12, "2025/01/31 12:00:00", 64, 1000005, 1, 190805, "2030/01/01 14:59:59", "カリン", -363.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 6, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 1.68, "2025/01/31 12:00:00", 64, 1000006, 1, 190805, "2030/01/01 14:59:59", "カリン", -363.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 7, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 2.33, "2025/01/31 12:00:00", 64, 1000007, 1, 190805, "2030/01/01 14:59:59", "カリン", -363.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (-6.0, 101, 3, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 7, 5.18, "2025/01/31 12:00:00", 61, 1020101, 10201, 133701, "2030/01/01 14:59:59", "ラビリスタ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (-2.0, 201, 1, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 2, 8.77, "2025/01/31 12:00:00", 61, 1020102, 10201, 133901, "2030/01/01 14:59:59", "クリスティーナ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 6, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 1, 15.5, "2025/01/31 12:00:00", 61, 1020103, 10201, 133801, "2030/01/01 14:59:59", "ネネカ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 2, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 5, 9.061, "2025/02/28 12:00:00", 61, 1020201, 10202, 134301, "2030/01/01 14:59:59", "ランファ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 2, 7.699, "2025/02/28 12:00:00", 61, 1020202, 10202, 134401, "2030/01/01 14:59:59", "チカ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 2, 8.595, "2025/03/31 12:00:00", 61, 1020301, 10203, 134601, "2030/01/01 14:59:59", "アオイ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 2, 7.758, "2025/03/31 12:00:00", 61, 1020302, 10203, 134501, "2030/01/01 14:59:59", "クローチェ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 2, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 6, 7.0, "2025/04/30 12:00:00", 61, 1020401, 10204, 132302, "2030/01/01 14:59:59", "ルイズマリー", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 2, 7.904, "2025/04/30 12:00:00", 61, 1020402, 10204, 132402, "2030/01/01 14:59:59", "イロハ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 4, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 2, 8.487, "2025/04/30 12:00:00", 61, 1020403, 10204, 132502, "2030/01/01 14:59:59", "ソノ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 2, 8.763, "2025/05/31 12:00:00", 61, 1020502, 10205, 134901, "2030/01/01 14:59:59", "カノン", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 3, 6.417, "2025/05/31 12:00:00", 61, 1020503, 10205, 134801, "2030/01/01 14:59:59", "ツムギ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 3, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 7, 10.335, "2025/06/30 12:00:00", 61, 1020601, 10206, 135001, "2030/01/01 14:59:59", "エリス", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 2, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 4, 6.281, "2025/06/30 12:00:00", 61, 1020602, 10206, 135101, "2030/01/01 14:59:59", "シェフィ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 1, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 2, 12.244, "2025/06/30 12:00:00", 61, 1020603, 10206, 135201, "2030/01/01 14:59:59", "プレシア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 2, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 8, 6.339, "2025/07/31 12:00:00", 61, 1020701, 10207, 135301, "2030/01/01 14:59:59", "クリア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 7, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 9, 8.184, "2025/07/31 12:00:00", 61, 1020702, 10207, 135401, "2030/01/01 14:59:59", "アネモネ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 9, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 2, 3.906, "2025/08/31 12:00:00", 61, 1020801, 10208, 129101, "2030/01/01 14:59:59", "アイラ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 2, 14.465, "2025/08/31 12:00:00", 61, 1020802, 10208, 129201, "2030/01/01 14:59:59", "シナツ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 4, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 3, 8.662, "2025/08/31 12:00:00", 61, 1020803, 10208, 100101, "2030/01/01 14:59:59", "ヒヨリ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 401, 1, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 3, 10.915, "2025/08/31 12:00:00", 61, 1020804, 10208, 100301, "2030/01/01 14:59:59", "レイ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 7, 6.042, "2025/09/30 12:00:00", 61, 1020901, 10209, 135802, "2030/01/01 14:59:59", "ユキノ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 4, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 1, 9.402, "2025/09/30 12:00:00", 61, 1020902, 10209, 135903, "2030/01/01 14:59:59", "サツキ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 8, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 1, 8.16, "2025/09/30 12:00:00", 61, 1020903, 10209, 136902, "2030/01/01 14:59:59", "ルルィ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 3, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 2, 5.0, "2025/10/31 12:00:00", 61, 1021001, 10210, 137401, "2030/01/01 14:59:59", "カスミ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 4, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 1, 8.12, "2025/10/31 12:00:00", 61, 1021002, 10210, 136001, "2030/01/01 14:59:59", "アラクネ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 4, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 2, 6.386, "2025/10/31 12:00:00", 61, 1021003, 10210, 136202, "2030/01/01 14:59:59", "ナーナ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 3, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 4, 7.438, "2025/11/30 12:00:00", 61, 1021101, 10211, 136402, "2030/01/01 14:59:59", "ユイ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 5, 8.35, "2025/11/30 12:00:00", 61, 1021102, 10211, 136302, "2030/01/01 14:59:59", "ミソラ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 2, 5.0, "2025/12/31 12:00:00", 61, 1021201, 10212, 136501, "2030/01/01 14:59:59", "シズル", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 2, 5.25, "2025/12/31 12:00:00", 61, 1021202, 10212, 137902, "2030/01/01 14:59:59", "リノ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 1, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 2, 7.5, "2025/12/31 12:00:00", 61, 1021203, 10212, 106801, "2030/01/01 14:59:59", "ラビリスタ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 2, 8.204, "2026/01/31 12:00:00", 61, 1021301, 10213, 126501, "2030/01/01 14:59:59", "ライラエル", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 2, 7.176, "2026/01/31 12:00:00", 61, 1021302, 10213, 129701, "2030/01/01 14:59:59", "ネフィ＝ネラ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 1, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 5, 8.602, "2026/01/31 12:00:00", 61, 1021303, 10213, 133101, "2030/01/01 14:59:59", "ヴァイオレット", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 102, 1, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 3, 10.14, "2026/02/06 12:00:00", 61, 1021304, 10213, 138101, "2030/01/01 14:59:59", "ライラエル", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 202, 1, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 7, 10.152, "2026/02/06 12:00:00", 61, 1021305, 10213, 138201, "2030/01/01 14:59:59", "ネフィ＝ネラ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 302, 4, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 3, 9.688, "2026/02/06 12:00:00", 61, 1021306, 10213, 138001, "2030/01/01 14:59:59", "ヴァイオレット", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 401, 2, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 1, 5.928, "2026/02/12 12:00:00", 61, 1021307, 10213, 138301, "2030/01/01 14:59:59", "ペコリーヌ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 4, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 2, 9.19, "2026/02/28 12:00:00", 61, 1021401, 10214, 138702, "2030/01/01 14:59:59", "ワカナ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 3, 8.724, "2026/02/28 12:00:00", 61, 1021402, 10214, 138802, "2030/01/01 14:59:59", "シオリ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 4, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 1, 7.758, "2026/03/31 12:00:00", 61, 1021501, 10215, 138902, "2030/01/01 14:59:59", "グレイス", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 6, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 4, 6.375, "2026/03/31 12:00:00", 61, 1021502, 10215, 139002, "2030/01/01 14:59:59", "キョウカ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 6, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 1, 6.173, "2026/03/31 12:00:00", 61, 1021503, 10215, 136902, "2030/01/01 14:59:59", "ルルィ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 6, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 2, 4.202, "2026/04/30 12:00:00", 61, 1021601, 10216, 139202, "2030/01/01 14:59:59", "ミホ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 6, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 1, 2.842, "2026/04/30 12:00:00", 61, 1021602, 10216, 139302, "2030/01/01 14:59:59", "マホ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 4, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 1, 4.598, "2026/04/30 12:00:00", 61, 1021603, 10216, 139402, "2030/01/01 14:59:59", "エリカ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 4, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 3, 6.533, "2026/05/31 12:00:00", 61, 1021701, 10217, 125802, "2030/01/01 14:59:59", "リリ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 301, 3, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 3, 5.0, "2026/05/31 12:00:00", 61, 1021702, 10217, 126102, "2030/01/01 14:59:59", "プレシア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 3, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 4, 5.214, "2026/05/31 12:00:00", 61, 1021703, 10217, 126002, "2030/01/01 14:59:59", "クリア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 102, 1, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 3, 8.781, "2026/05/31 12:00:00", 61, 1021704, 10217, 139501, "2030/01/01 14:59:59", "リリ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 202, 2, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 1, 6.529, "2026/05/31 12:00:00", 61, 1021705, 10217, 139601, "2030/01/01 14:59:59", "クリア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 302, 3, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 2, 3.195, "2026/05/31 12:00:00", 61, 1021706, 10217, 139701, "2030/01/01 14:59:59", "プレシア", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 2, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 3, 12.43, "2026/06/30 12:00:00", 61, 1021801, 10218, 139902, "2030/01/01 14:59:59", "ルイズマリー", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 2, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 3, 6.35, "2026/06/30 12:00:00", 61, 1021802, 10218, 140001, "2030/01/01 14:59:59", "クレジッタ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 101, 1, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 5, 10.23, "2026/07/31 12:00:00", 61, 1021901, 10219, 140102, "2030/01/01 14:59:59", "フブキ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 201, 1, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 2, 5.584, "2026/07/31 12:00:00", 61, 1021902, 10219, 140201, "2030/01/01 14:59:59", "ヴァンピィ", -285.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 1, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 3.414, "2026/04/10 12:00:00", 62, 2000001, 2, 190801, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 2, 1, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 3.099, "2026/04/10 12:00:00", 62, 2000002, 2, 190801, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 3, 1, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 2.801, "2026/04/10 12:00:00", 63, 2000003, 2, 190801, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 4, 2, "報酬がもらえますよ！\nチェックしてみてください", 2, 0.0, "2026/04/10 12:00:00", 63, 2000004, 2, 190801, "2030/01/01 14:59:59", "カリン", -416.5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 5, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 2.12, "2026/04/10 12:00:00", 64, 2000005, 2, 190801, "2030/01/01 14:59:59", "カリン", -363.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 6, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 1.68, "2026/04/10 12:00:00", 64, 2000006, 2, 190801, "2030/01/01 14:59:59", "カリン", -363.0);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (0.0, 7, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 2.33, "2026/04/10 12:00:00", 64, 2000007, 2, 190801, "2030/01/01 14:59:59", "カリン", -363.0);
